#include <iostream>
#include <string>

int main() {
    std::string user_input;
    std::getline(std::cin, user_input);
    if (user_input.length() == 0) {
        std::cout << "" << std::endl;
        return 0;
    }
    std::string modified = user_input[0] + user_input.substr(1, user_input.length() - 2).replace("dot", ".") + user_input.back();
    // Since std::string::replace requires position and length, we need to handle replacements carefully
    // Let's do replacements manually
    // First, replace "dot" in the middle
    size_t start_pos = 1;
    size_t end_pos = user_input.length() - 1;
    std::string middle = user_input.substr(1, user_input.length() - 2);
    size_t pos;
    while ((pos = middle.find("dot")) != std::string::npos) {
        middle.replace(pos, 3, ".");
    }
    // Reconstruct the string
    modified = user_input[0] + middle + user_input.back();

    // Now replace "at" with "@" in the first occurrence
    size_t at_pos = modified.find("at");
    if (at_pos != std::string::npos) {
        modified.replace(at_pos, 2, "@");
    }

    std::cout << modified << std::endl;
    return 0;
}
